import{_ as n,C as a,o as p,c as i,j as o,a as l,E as t,aD as d}from"./chunks/framework.BpOiDbEB.js";const x=JSON.parse('{"title":"视频导出","description":"","frontmatter":{},"headers":[],"relativePath":"export/video.md","filePath":"export/video.md","lastUpdated":null}'),c={name:"export/video.md"};function _(h,e,m,P,b,f){const r=a("NolebasePageProperties"),s=a("NolebaseGitChangelog");return p(),i("div",null,[e[0]||(e[0]=o("h1",{id:"视频导出",tabindex:"-1"},[l("视频导出 "),o("a",{class:"header-anchor",href:"#视频导出","aria-label":'Permalink to "视频导出"'},"​")],-1)),t(r),e[1]||(e[1]=d('<p></p><p>本页面统一说明视频导出、片段导出和批量导出的使用方式。</p><h2 id="视频导出-1" tabindex="-1">视频导出 <a class="header-anchor" href="#视频导出-1" aria-label="Permalink to &quot;视频导出&quot;">​</a></h2><p>视频导出会将谱面预览渲染为 MP4 文件。可调整导出范围、分辨率、画面比例、帧率、音频码率和输出路径。</p><h2 id="片段导出" tabindex="-1">片段导出 <a class="header-anchor" href="#片段导出" aria-label="Permalink to &quot;片段导出&quot;">​</a></h2><p>片段导出使用导出范围选择器，只输出指定时间范围内的预览内容。</p><h2 id="批量导出" tabindex="-1">批量导出 <a class="header-anchor" href="#批量导出" aria-label="Permalink to &quot;批量导出&quot;">​</a></h2><p>批量导出允许用户指定一个输出目录，多个谱面的导出结果会统一保存到该目录中。</p><p>预览画面与导出画面使用同一套渲染体系，但导出时可以使用不同的分辨率和画面比例，因此两者不保证像素尺寸完全一致。</p><p>当前源码提供 1:1、4:3 和 16:9 画面比例，帧率包括 30、60 和 120 FPS，音频码率包括 128、160、192、256 和 320 kbps。</p><p>视频处理和部分媒体工具依赖 FFmpeg。程序会优先寻找程序目录附近的 FFmpeg，也支持通过 <code>MIACODE_FFMPEG_PATH</code> 指定路径。</p>',11)),t(s)])}const N=n(c,[["render",_]]);export{x as __pageData,N as default};
